import axios from "axios";

const api = axios.create({
  baseURL:
    process.env.REACT_APP_API_URL ||
    "http://localhost/dashboard_analitico/backend/api",
});

export const fetchStats = async (period = "month", startDate = null, endDate = null) => {
  const params = { period };

  if (startDate) params.startDate = startDate;
  if (endDate) params.endDate = endDate;

  const response = await api.get("/stats.php", { params });
  return response; // o response.data si lo prefieres
};

export default api;
